<script lang="ts">import type { Unit } from '../engine/contract'; type Props = { unit: Unit }; let { unit }: Props = $props(); const hpPercent = $derived((unit.hp / unit.maxHp) * 100);</script>
<article class:enemy={unit.faction === 'enemy'} class="unit-strip"><header><span class="lamp" class:off={!unit.canMove}></span><span class="lamp attack" class:off={!unit.canAttack}></span><b>{unit.name}</b></header><div class="readout"><span>HP {unit.hp}/{unit.maxHp}</span><span>ATK {unit.attack}</span></div><div class="hp"><i style={`--hp:${hpPercent / 100}`}></i></div>{#if unit.armor}<small>ARM {unit.armor}</small>{/if}{#if unit.debt}<small class="debt">DEBT {unit.debt}</small>{/if}</article>
<style>.unit-strip { width: 136px; padding: 6px; border: 1px solid var(--steel); background: var(--ivory-1); color: var(--ink); box-shadow: var(--shadow-lift); } .unit-strip.enemy { background: #d9cfbb; } header { display: flex; gap: 4px; align-items: center; } b { margin-left: 2px; font-size: 9px; letter-spacing: -.04em; } .lamp { width: 5px; height: 5px; border-radius: 50%; background: var(--move); } .lamp.attack { background: var(--amber); } .lamp.off { background: var(--steel); } .readout { display: flex; justify-content: space-between; margin-top: 5px; font-size: 8px; } .hp { height: 3px; margin-top: 4px; overflow: hidden; background: var(--steel-light); } .hp i { display: block; width: 100%; height: 100%; background: var(--ink); transform: scaleX(var(--hp)); transform-origin: left; transition: transform 300ms var(--needle-spring); } small { display: inline-block; margin-top: 4px; margin-right: 5px; font-size: 7px; } .debt { color: var(--signal-red); }</style>
